raws:
{
  "pick": 1,
  "name_zh": "毒刃連擊",
  "concept": "透過連續的揮砍在目標身上留下致命的裂口。",
  "cast_flavor": "利刃劃過空氣的尖銳聲響，緊接著是滲出的暗紫色液體。"
}

{
  "pick": 0,
  "name_zh": "裂地之怒",
  "concept": "將積聚的怒火轉化為大地的震顫，引發劇烈的崩裂。",
  "cast_flavor": "雙手重重拍向地面，讓狂暴的情緒化作岩層的破碎聲。"
}

{
  "pick": 1,
  "name_zh": "暗影束縛之種",
  "concept": "在目標體表植入不穩定的暗影核心，隨後引爆周遭的黑暗。",
  "cast_flavor": "陰影在目標身上蠕動、炸裂，吞噬周圍的微光。"
}

{
  "pick": 1,
  "name_zh": "暗影裂解之種",
  "concept": "將不穩定的黑暗核心植入目標，隨後在目標崩解時引發連鎖爆炸。",
  "cast_flavor": "陰影在目標身上蠕動、炸裂，吞噬周圍的微光。"
}

{
  "pick": 0,
  "name_zh": "霜結之衝",
  "concept": "匯聚寒氣並將敵人強行拉向術者的寒冰衝擊。",
  "cast_flavor": "冰霜凝聚成錐形，將目標拽向寒冷的中心。"
}

{
  "pick": 3,
  "name_zh": "流轉風紋",
  "concept": "於空氣中留下流動的氣流軌跡。",
  "cast_flavor": "指尖輕撥，看不見的氣流在半空交織成網。"
}

{
  "pick": 0,
  "name_zh": "聖紋之印",
  "concept": "在地面刻劃出無形的符文，等待力量的點燃。",
  "cast_flavor": "法器劃過地面，留下一道閃爍的微光。"
}

{
  "pick": 0,
  "name_zh": "聖紋之痕",
  "concept": "於地面鐫刻出專屬的符文，在光輝中顯現其形跡。",
  "cast_flavor": "法器劃過地面，留下一道閃爍的微光。"
}

{
  "pick": 2,
  "name_zh": "迴旋風壓",
  "concept": "透過法器引動空氣流動，使周遭的元素擴散開來。",
  "cast_flavor": "法器輕旋，將周遭的風勢向四周推開。"
}

{
  "pick": 2,
  "name_zh": "風湧擴散",
  "concept": "利用法器引導流動的氣流，讓周遭的元素向外蔓延。",
  "cast_flavor": "法器輕旋，將氣流導向四周，使元素隨風擴散。"
}

{
  "pick": 0,
  "name_zh": "高空突刺",
  "concept": "利用俯瞰之勢，將法力轉化為推開敵人的強大氣流。",
  "cast_flavor": "從高處傾瀉而下的氣流，將阻礙的路徑悉數推開。"
}

{
  "pick": 0,
  "name_zh": "幽影之墜",
  "concept": "將積蓄的黑暗力量匯聚於法器，藉由毀滅性的衝擊將目標擊倒。",
  "cast_flavor": "黑暗從法器中噴湧而出，伴隨著沉悶的撞擊聲，將眼前的一切壓入塵土。"
}

{
  "pick": 1,
  "name_zh": "寒霜之紋",
  "concept": "在周遭地面刻下冰冷的符文，並使敵人在刺痛中流血。",
  "cast_flavor": "劍尖划過冰層，裂開的縫隙正不斷滲出殷紅。"
}

{
  "pick": 2,
  "name_zh": "重擊衝撞",
  "concept": "藉由武器的重量與力道，強行將對手撞離原位。",
  "cast_flavor": "揮動沉重的兵刃，將目標勢不可擋地推向遠方。"
}

{
  "pick": 0,
  "name_zh": "俯瞰之眼",
  "concept": "站在高點觀察時，能輕易鎖定目標的脆弱之處。",
  "cast_flavor": "當身處高處俯視敵陣，那道無形的視線已將目標徹底鎖定。"
}

{
  "pick": 1,
  "name_zh": "雷光之印",
  "concept": "透過法器引導電弧，在目標身上留下閃爍的符文。",
  "cast_flavor": "無聲的電光在空氣中跳躍，將光芒鎖定在對方的脊背。"
}

{
  "pick": 1,
  "name_zh": "獵殺標記",
  "concept": "從高處投射出帶有追踪特性的箭矢，鎖定目標的生機。",
  "cast_flavor": "箭矢劃破空氣，在目標身上留下無法擺脫的印記。"
}

{
  "pick": 1,
  "name_zh": "追逐標記",
  "concept": "利用射擊的軌跡，在目標身上刻劃出無法逃脫的狩獵印記。",
  "cast_flavor": "箭矢劃破空氣，在目標身上留下無法擺脫的標記。"
}

{
  "pick": 2,
  "name_zh": "神啟之誓",
  "concept": "透過高頻率的震盪在目標身上留下無法逃脫的印記。",
  "cast_flavor": "光芒穿透了防禦的縫隙，將目標鎖定在神聖的律動之中。"
}

{
  "pick": 2,
  "name_zh": "暗影之鎖",
  "concept": "透過遠距離投射出的陰影，將目標緊緊鎖定在既定路徑上。",
  "cast_flavor": "漆黑的絲線在空中交織，強行將對方的行動限制在陰影之中。"
}

{
  "pick": 0,
  "name_zh": "凝視之息",
  "concept": "將全身專注轉化為無聲的壓力，令敵人的感官陷入死寂。",
  "cast_flavor": "當所有的呼吸都止於這一刻，世界只剩下絕對的靜謐。"
}

{
  "pick": 0,
  "name_zh": "暗影重壓",
  "concept": "匯聚所有進攻節奏，釋放出足以撕裂視覺的漆黑衝擊。",
  "cast_flavor": "隱藏在陰影中的殺意，在終結一擊時徹底爆裂。"
}

{
  "pick": 1,
  "name_zh": "火光吐息",
  "concept": "匯聚體內氣息轉化為熾熱的噴流。",
  "cast_flavor": "法器尖端綻放出耀眼的火光，將積蓄的氣息噴射而出。"
}

{
  "pick": 0,
  "name_zh": "聖紋之位",
  "concept": "在戰場上劃出無形的界限，為後續的進攻預留座標。",
  "cast_flavor": "將光芒落點於地面，指引著獵物的終局。"
}

{
  "pick": 1,
  "name_zh": "迷霧火環",
  "concept": "透過燃燒空氣引發的擴散性熱浪，並伴隨著濃稠的煙塵。",
  "cast_flavor": "熾熱的氣流在周遭爆裂，隨即被厚重的黑煙籠罩。"
}

{
  "pick": 1,
  "name_zh": "高處墜落之擊",
  "concept": "利用高度差製造強大的撞擊力道，封閉對手的咒語出口。",
  "cast_flavor": "從高處俯瞰，將箭矢或重擊直搗對方的咽喉。"
}

{
  "pick": 0,
  "name_zh": "寒霜怒意",
  "concept": "在承受痛楚時將寒氣轉化為憤怒的能量。",
  "cast_flavor": "冰霜與怒火在受創的瞬間交織，於體表凝結。"
}

{
  "pick": 3,
  "name_zh": "腐蝕陷阱",
  "concept": "將不詳的毒素隱藏在地面之下，等待踏入者觸發。",
  "cast_flavor": "泥土翻湧出暗淡的綠光，空氣中瀰漫著令人窒息的惡臭。"
}
